@Composable fun QuizScreen(repository:BookRepository,progress:ProgressStore,reviewErrors:Boolean,back:()->Unit){var key by remember{mutableIntStateOf(0)};val pref=if(reviewErrors)progress.quizWrongSections else progress.completed;val qs=remember(key,reviewErrors,pref){repository.quizQuestions(pref,10)};if(qs.isEmpty()){EmptyStudyState("Пока недостаточно материала для проверки.","Пройди несколько тем и вернись к тесту.",back);return};var index by remember(key){mutableIntStateOf(0)};var selected by remember(key,index){mutableStateOf<Int?>(null)};var correct by remember(key){mutableIntStateOf(0)};val missed=remember(key){mutableStateListOf<String>()};if(index>=qs.size){QuizFinish(correct,qs.size,missed.toList(),{key++},back);return};val q=qs[index];val answered=selected!=null;Column(Modifier.fillMaxSize()){Row(Modifier.fillMaxWidth().padding(10.dp,8.dp),verticalAlignment=Alignment.CenterVertically){IconButton(onClick=back){Icon(Icons.Outlined.ArrowBack,"Назад")};Column(Modifier.weight(1f)){Kicker(if(reviewErrors)"Повторение ошибок" else "Быстрая проверка");Text("Вопрос ${index+1} из ${qs.size}",style=MaterialTheme.typography.titleSmall)};Text("$correct/${index+if(answered)1 else 0}",fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.secondary)};LinearProgressIndicator(progress=(index+if(answered)1 else 0).toFloat()/qs.size,modifier=Modifier.fillMaxWidth());LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{ElevatedCard(Modifier.fillMaxWidth(),shape=RoundedCornerShape(22.dp)){Column(Modifier.padding(18.dp)){Kicker("Фрагмент из книги");Spacer(Modifier.height(8.dp));if(q.arabicHeavy)CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl){Text(q.prompt,Modifier.fillMaxWidth(),textAlign=TextAlign.End,style=TextStyle(fontFamily=arabicFont(progress.settings),fontSize=(23f*progress.settings.arabicScale).sp,lineHeight=(36f*progress.settings.arabicScale).sp,textDirection=TextDirection.Rtl,color=MaterialTheme.colorScheme.onSurface))}else Text(styledMixedText(q.prompt,progress.settings),style=MaterialTheme.typography.bodyLarge.copy(textDirection=TextDirection.Ltr),color=CardHeadlineBrown)}}};item{Text("К какой теме относится этот фрагмент?",style=MaterialTheme.typography.titleSmall,color=CardHeadlineBrown)};items(q.options.size){oi->val co=oi==q.correctIndex;val so=oi==selected;val cc=when{answered&&co->MaterialTheme.colorScheme.primaryContainer;answered&&so&&!co->MaterialTheme.colorScheme.errorContainer;else->MaterialTheme.colorScheme.surface};val bc=when{answered&&co->MaterialTheme.colorScheme.primary;answered&&so&&!co->MaterialTheme.colorScheme.error;else->NestedSageBorder};OutlinedCard(modifier=Modifier.fillMaxWidth(),onClick={if(!answered){selected=oi;val hit=oi==q.correctIndex;if(hit)correct++ else if(!missed.contains(q.sectionTitle))missed+=q.sectionTitle;progress.recordQuiz(q.sectionId,hit)}},shape=RoundedCornerShape(18.dp),colors=CardDefaults.outlinedCardColors(containerColor=cc),border=BorderStroke(1.dp,bc)){Row(Modifier.padding(15.dp),verticalAlignment=Alignment.CenterVertically){Surface(Modifier.size(30.dp),shape=RoundedCornerShape(99.dp),color=if(answered&&co)MaterialTheme.colorScheme.primary else NestedSage){Box(contentAlignment=Alignment.Center){Text(('A'.code+oi).toChar().toString(),fontWeight=FontWeight.Bold)}};Spacer(Modifier.width(12.dp));Text(q.options[oi],Modifier.weight(1f),style=MaterialTheme.typography.bodyMedium,color=CardHeadlineBrown)}}};if(answered){item{Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(containerColor=if(selected==q.correctIndex)MaterialTheme.colorScheme.primaryContainer.copy(alpha=.55f) else MaterialTheme.colorScheme.errorContainer.copy(alpha=.55f))){Column(Modifier.padding(16.dp)){Text(if(selected==q.correctIndex)"Верно" else "Нужно повторить",fontWeight=FontWeight.Bold,color=CardHeadlineBrown);Text("Правильная тема: ${q.sectionTitle}")}}};item{Button(onClick={index++;selected=null},Modifier.fillMaxWidth()){Text(if(index==qs.lastIndex)"Завершить" else "Следующий вопрос")}}}}}}
@Composable private fun QuizFinish(correct:Int,total:Int,missedTitles:List<String>,onAgain:()->Unit,onBack:()->Unit){val percent=if(total==0)0 else ((correct*100f)/total).toInt();LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Kicker("Результат");Text("$correct из $total",style=MaterialTheme.typography.titleLarge.copy(fontSize=38.sp),color=CardHeadlineBrown);Text("$percent% правильных ответов",color=MaterialTheme.colorScheme.onSurfaceVariant)};if(missedTitles.isNotEmpty()){item{SectionTitle("Повторить","Темы с ошибками")};items(missedTitles.size){i->OutlinedCard(Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp),border=BorderStroke(1.dp,NestedSageBorder)){Text(missedTitles[i],Modifier.padding(14.dp),color=CardHeadlineBrown)}}};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton(onClick=onBack,modifier=Modifier.weight(1f)){Text("Назад")};Button(onClick=onAgain,modifier=Modifier.weight(1f)){Icon(Icons.Outlined.Refresh,null);Spacer(Modifier.width(5.dp));Text("Ещё раз")}}}}}
